<script setup>
import { ref, onMounted, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { useAppStore } from '../stores/app'
import api from '../api/client'
import MetricCharts from '../components/MetricCharts.vue'
const app=useAppStore(), router=useRouter(), source=ref('fs'), runs=ref([]), selected=ref(null), metrics=ref(null)
async function load(){ runs.value=await api.get(source.value==='fs'?'/training/fs-runs':'/training/runs'); selected.value=null; metrics.value=null }
async function select(row){ selected.value=row; const id=source.value==='fs' ? row.results_dir.split('/').filter(Boolean).at(-1) : row.id || row.run_id; metrics.value=await api.get(`/training/${source.value==='fs'?'fs-runs':'runs'}/${encodeURIComponent(id)}/metrics`) }
async function sync(){ const data=await api.post('/training/sync-results'); ElMessage.success(`已导入 ${data.imported} 条，跳过 ${data.skipped} 条`) }
function restore(){ const c=selected.value.config_json; const config=c.config || c; app.env={preset_name:'default',config:structuredClone(config)}; app.train={...app.train,...Object.fromEntries(['gat_hidden_dim','actor_hidden_dim','critic_hidden_dim','actor_learning_rate','critic_learning_rate','gamma','gae_lambda','ppo_clip','ppo_epochs','ppo_batch_size','ent_coef','eval_interval'].filter(k=>config[k] != null).map(k=>[k,config[k]])), model_type:selected.value.model_type,episodes:selected.value.episodes,seed:selected.value.seed,device:selected.value.device,threads:selected.value.threads}; router.push('/') }
function sandbox(){ router.push({path:'/sandbox',state:{checkpoint:selected.value.best_checkpoint || selected.value.last_checkpoint}}) }
onMounted(load); watch(source,load)
</script>
<template><div class="page"><div class="page-head"><div><div class="eyebrow">EXPERIMENT ARCHIVE</div><h1>实验记录与模型资产</h1><p>浏览训练曲线、恢复实验配置或加载模型推演。</p></div><div class="page-code">实验档案 / 04</div></div><section class="panel"><div class="panel-heading"><div><div class="eyebrow">RUNS</div><h3>训练记录 <span class="count">{{ runs.length }}</span></h3></div><div class="history-actions"><el-radio-group v-model="source"><el-radio-button value="fs">磁盘 results/</el-radio-button><el-radio-button value="db">MySQL</el-radio-button></el-radio-group><el-button @click="sync">同步 results/ 到 MySQL</el-button></div></div><p v-if="!app.health?.db_connected" class="notice">MySQL 未连接：可直接浏览磁盘实验和训练曲线。</p><el-table :data="runs" highlight-current-row @row-click="select"><el-table-column prop="run_name" label="实验名称" min-width="180"/><el-table-column prop="model_type" label="模型" width="110"/><el-table-column prop="status" label="状态" width="110"/><el-table-column label="回合" width="130"><template #default="{row}">{{ row.current_episode }} / {{ row.episodes }}</template></el-table-column><el-table-column prop="seed" label="种子" width="85"/><el-table-column label="最佳得分" width="110"><template #default="{row}">{{ row.best_score == null ? '—' : Number(row.best_score).toFixed(4) }}</template></el-table-column><el-table-column prop="results_dir" label="结果目录" min-width="220" show-overflow-tooltip/></el-table></section><section v-if="selected" class="history-detail"><div class="panel panel-heading"><div><div class="eyebrow">SELECTED RUN</div><h3>{{ selected.run_name }}</h3><p class="muted">{{ selected.results_dir }}</p></div><div><el-button @click="restore">回填参数到工作台</el-button><el-button type="primary" :disabled="!selected.best_checkpoint && !selected.last_checkpoint" @click="sandbox">加载模型到沙盘</el-button></div></div><MetricCharts v-if="metrics" :metrics="metrics"/></section></div></template>
